def components(g,bg):
    h,w=len(g),len(g[0]); seen=set(); comps=[]
    def dfs(i,j,c):
        st=[(i,j)]
        while st:
            a,b=st.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); c.append((a,b))
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    x,y=a+di,b+dj
                    if 0<=x<h and 0<=y<w and g[x][y]!=bg and (x,y) not in seen: st.append((x,y))
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                c=[]; dfs(i,j,c); comps.append(c)
    return comps
